/bin/zsh -lc "cat > main.go.tmp <<'EOF'
package main

import (
	\"crypto/rand\"
	\"fmt\"
	\"math/big\"
	\"os\"
	\"text/template\"
)

func main() {
	n, err := rand.Int(rand.Reader, big.NewInt(1<<31))
	if err "'!= nil {
		fmt.Fprintln(os.Stderr, "generate random integer:", err)
		os.Exit(1)
	}

	tmpl, err := template.New("greeting").Parse("Hello World {{.}}'"\\n\")
	if err "'!= nil {
		fmt.Fprintln(os.Stderr, "parse greeting template:", err)
		os.Exit(1)
	}
	if err := tmpl.Execute(os.Stdout, n); err != nil {
		fmt.Fprintln(os.Stderr, "render greeting template:", err)
		os.Exit(1)
	}
}
EOF
python3 -c '"'import os; p=\"main.go.tmp\"; f=open(p,\"rb\"); data=f.read(); f.close(); t=\"main.go.tmp.write\"; g=open(t,\"wb\"); g.write(data); g.flush(); os.fsync(g.fileno()); g.close(); os.replace(t,\"main.go\")'"

